class Solution:

	def solve(self, p):
		if p is None:
			return 0
		left = self.solve(p.left)
		right = self.solve(p.right)
		self.ans += abs(left) + abs(right)
		return p.data - 1 + left + right

	def distributeCandy(self, root):
		self.ans = 0
		self.solve(root)
		return self.ans
